const doors=[['Двері 3-01','green',19,38],['Двері 3-02','green',39,28],['Двері 3-03','red',65,38],['Двері 3-04','green',43,62],['Двері 3-05','yellow',67,74],['Двері 3-06','green',86,51],['Турнікет персонал','blue',34,47]];const events=[['Доступ дозволено','Олексій Мельник · Двері 3-01','green','15:42:18'],['Доступ дозволено','Ірина Коваль · Турнікет персонал','green','15:41:52'],['Відмовлено у доступі','Невідома картка · Двері 3-03','denied','15:40:11'],['Двері відчинені понад норму','Двері 3-05 · 01:37','warn','15:38:46'],['Доступ дозволено','Катерина Бойко · Двері 3-04','green','15:37:05']];let selected=doors[0],action='';
const icon={ 'Плани':'⌘','Події':'◷','Точки доступу':'▣','Пристрої':'◈','Редактор плану':'✥','Журнал аудиту':'▤','Інтеграція':'⚙'};function nav(){return Object.keys(icon).map((x,i)=>`<div class="nav-item ${!i?'active':''}"><span class="nav-icon">${icon[x]}</span>${x}</div>`).join('')}function render(){document.querySelector('#app').innerHTML=`<div class="app"><aside class="sidebar"><div class="brand"><div class="shield">U</div><div>U-PROX<small>SECURITY CENTER</small></div></div><div class="nav-label">ОПЕРАЦІЙНИЙ ЦЕНТР</div>${nav()}<div class="nav-label">АДМІНІСТРУВАННЯ</div><div class="nav-item"><span class="nav-icon">⚙</span>Налаштування</div><div class="side-status"><b class="online">● СИСТЕМА В МЕРЕЖІ</b><small style="display:block;color:#8092aa;margin-top:6px">U-PROX API · MOCK MODE</small></div><div class="operator"><div class="avatar">ОМ</div><div><b>Олександр М.</b><small>Оператор безпеки</small></div></div></aside><main class="main"><header class="top"><div class="crumb">Живий план <span>Головна будівля / 3 поверх</span></div><div class="controls"><button class="select">Головна будівля⌄</button><button class="select">3 поверх⌄</button><button class="iconbtn">⛶</button><button class="iconbtn">⊞</button></div></header><section class="floor"><div class="plan"><div class="map-title">3 ПОВЕРХ · МАСШТАБ 1:250</div><div class="room r1">OPEN SPACE · 301</div><div class="room r2">ПЕРЕГОВОРНА · 302</div><div class="room r3">ВІДДІЛ РОЗРОБКИ</div><div class="room r4">LAB · 304</div><div class="room r5">КОРИДОР B</div><div class="corridor"></div>${doors.map((d,i)=>`<button class="marker ${d[1]} ${selected[0]===d[0]?'selected':''}" data-i="${i}" data-label="${d[0]}" style="left:${d[2]}%;top:${d[3]}%">${i===6?'↔':'↔'}</button>`).join('')}</div><div class="map-toolbar"><button>+</button><button>−</button><button>⊙</button></div></section></main><aside class="right"><div class="feed-head"><h2>Живі події</h2><span class="live">● LIVE</span></div><div class="feed">${events.map(e=>`<article class="event ${e[2]}"><i class="dot"></i><div><div class="event-main"><b>${e[0]} ${e[2]==='denied'?'<span class="badge">ВІДМОВА</span>':''}</b><time>${e[3]}</time></div><p>${e[1]}</p></div></article>`).join('')}</div><div class="details"><div class="details-title"><div><h3>${selected[0]}</h3><small>Контролер U-PROX IC A · Reader 02</small></div><div class="state">● НОРМА</div></div><div class="detail-grid"><div><span>ОСТАННЯ ПОДІЯ</span><b>Доступ дозволено</b></div><div><span>ЧАС</span><b>15:42:18</b></div><div><span>ОСТАННЯ ОСОБА</span><b>Олексій Мельник</b></div><div><span>НАПРЯМОК</span><b>Вхід</b></div></div><div class="actions"><button class="button primary" data-action="Відкрити">Відкрити</button><button class="button" data-action="Доступ: вхід">Доступ: вхід</button><button class="button" data-action="Доступ: вихід">Доступ: вихід</button><button class="button danger" data-action="Заблокувати">Заблокувати</button></div></div></aside></div><div class="modal"><div class="dialog"><h2>Підтвердіть ручну дію</h2><p id="dialogText"></p><div class="actions"><button class="button" id="cancel">Скасувати</button><button class="button primary" id="confirm">Підтвердити</button></div></div></div><div class="toast">✓ Дію передано до захищеного шлюзу та журналу аудиту</div>`;document.querySelectorAll('.marker').forEach(x=>x.onclick=()=>{selected=doors[x.dataset.i];render()});document.querySelectorAll('[data-action]').forEach(x=>x.onclick=()=>openAction(x.dataset.action));}
function openAction(a){action=a;document.querySelector('#dialogText').textContent=`Ви збираєтеся виконати дію «${a}» для «${selected[0]}». Операція буде перевірена за правами доступу та зафіксована в журналі аудиту.`;document.querySelector('.modal').classList.add('show');document.querySelector('#cancel').onclick=()=>document.querySelector('.modal').classList.remove('show');document.querySelector('#confirm').onclick=()=>{document.querySelector('.modal').classList.remove('show');const t=document.querySelector('.toast');t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}}render();setInterval(()=>{const t=document.querySelector('.live');if(t)t.textContent='● LIVE'},2000);
